import {DELIVERY,PROCUREMENT} from './facility-layout.js';
import {CATALOG,physicalOffline} from './operations.js';
import {freeRackSlot} from './play-rules.js';
// Objectives are derived from the actual world, so one player's work advances the team.
export function nextObjective(ops,nodes,links,network){
 const g=ops.game,byId=Object.fromEntries(nodes.map(n=>[n.id,n])),active=ops.available(),stock=g.stock;
 const item=sku=>stock.find(s=>s.sku===sku),name=sku=>CATALOG.find(c=>c.id===sku)?.name||sku;
 const order=(sku,why)=>({kind:'order',sku,title:`Order ${name(sku)}`,detail:why||'Use the procurement kiosk.',where:'STAGING',x:PROCUREMENT.x,z:PROCUREMENT.z});
 const receive=sku=>{const o=g.orders.find(o=>o.sku===sku&&!o.opened);return o?{kind:Date.now()<o.arrives?'wait':'unbox',order:o.id,sku,title:Date.now()<o.arrives?`Delivery arriving in ${Math.ceil((o.arrives-Date.now())/1000)}s`:`Open the ${name(sku)} box`,detail:'At staging, press E on the box.',where:'STAGING',x:DELIVERY.x,z:DELIVERY.z}:null;};
 function supply(sku,why){return receive(sku)||order(sku,why);}
 function cable(a,b,pa,pb,sku){const s=item(sku);if(!s)return supply(sku,`Connect ${a.id} to ${b.id}.`);const second=s.anchor?.a===a.id&&s.anchor.pa===a.ports.indexOf(pa),n=second?b:a,p=second?pb:pa;return {kind:'patch',sku,stock:s.id,a:a.id,b:b.id,pa:a.ports.indexOf(pa),pb:b.ports.indexOf(pb),node:n.id,title:`Connect ${a.id} → ${b.id}`,detail:`${a.id}: ${pa.displayName||pa.name} (${pa.side||'rear'}) → ${b.id}: ${pb.displayName||pb.name} (${pb.side||'front'}) · E at each port.`,where:n.rack,x:n.pos.x,z:n.pos.z+(p.side==='rear'?-6:6)};}

 function commission(n){if(n.physical){const psu=n.physical.power.findIndex(x=>!x);if(psu>=0){const s=item('power');return s?{kind:'power',node:n.id,stock:s.id,psu,title:`Connect ${n.id} PSU ${psu?'B':'A'}`,detail:`Press E near the device to connect PDU ${psu?'B':'A'}.`,where:n.rack,x:n.pos.x,z:-6}:supply('power');}if(!n.physical.on)return {kind:'boot',node:n.id,title:`Power on ${n.id}`,detail:'Press E at the device.',where:n.rack,x:n.pos.x,z:6};if(n.physical.bootUntil>Date.now())return {kind:'wait',node:n.id,title:`${n.id} is starting`,detail:'Boot completes automatically.',where:n.rack,x:n.pos.x,z:6};}
 const p=n.ports.find(p=>p.name==='MGMT UPLINK');if(p&&!p.link){const hub=byId['MGMT-SW'],hp=hub.ports.find(p=>p.name==='MGMT-1'&&!p.service&&!p.link&&p.speed===1)||hub.ports.find(p=>!p.service&&!p.link&&p.speed===1);if(hp)return cable(n,hub,p,hp,'cat6');}
 if(n.net.ip==='0.0.0.0'||!n.net.ssh||n.net.vlan!==70||!network.reachable(byId['MGMT-SW'],n,70)){return {kind:'configure',node:n.id,title:`Configure ${n.id} management`,detail:'Either title · local console/KVM · unique 10.10.70.x/24 · VLAN 70 · SSH on. Both management cable ports must use VLAN 70.',where:n.rack,x:n.pos.x,z:6};}return null;
 }
 if(g.mode==='free'||g.track==='levels')return null;
 if(g.mode==='challenge'){const c=g.challenge;if(!c?.started)return {kind:'begin',title:'Begin the selected challenge',detail:'J opens the objective. The facility stays healthy until Begin.'};if(c.finished)return {kind:'results',title:'Challenge complete',detail:'J shows your result.'};if(c.index!==0)return {kind:'diagnose',title:'Investigate and restore service',detail:'Check monitoring, interfaces and affected hardware with either title. J → Validate when healthy.'};}
 if(g.incident)return {kind:'diagnose',title:'Restore production service',detail:'Inspect monitoring. Repair the affected path, then J → Validate.'};
 const project=g.mode==='campaign'?ops.validation().project:{types:{server:1}},need=project.types|| (project.dr?{server:1,storage:1}:project.sku?{storage:active.filter(n=>n.type==='storage').length+(!active.some(n=>n.spec?.sku===project.sku)?1:0)}:{});
 const installed=active.filter(n=>n.spec);
 for(const n of installed){const task=commission(n);if(task)return task;}
 for(const [type,count]of Object.entries(need)){const existing=installed.filter(n=>n.type===type&&(!project.dr||n.site==='dr'));if(existing.length>=count)continue;const sku=project.sku||{switch:'switch24',server:'server2',storage:'array',san:'san32',gpu:'gpu',firewall:'firewall'}[type];const c=CATALOG.find(c=>c.id===sku),s=item(sku);if(!s)return supply(sku,`${existing.length}/${count} ${type} devices installed.`);
 const rack=project.dr?(type==='server'?'R05':'R06'):{switch:'R01',server:'R02',storage:'R03',san:'R03',gpu:'R04',firewall:'R01'}[type];let rail=g.rails.find(r=>!r.used&&r.units===c.units),unit=rail?.unit;const r=rail?.rack||rack;
 if(!rail){unit=freeRackSlot(nodes,g.rails,r,c.units);if(!unit)return {kind:'space',title:`Find ${c.units}U of free rack space`,detail:'Remove unused equipment or install an expansion rack.'};const rs=item('rail');if(!rs)return supply('rail');return {kind:rs.holders.length?'rails':'pickup',install:'rails',stock:rs.id,sku:'rail',device:s.id,rack:r,unit,units:c.units,title:rs.holders.length?`Install rails in ${r} U${unit}`:'Pick up the rail kit',detail:rs.holders.length?'Walk to the highlighted rack and press E.':'At the opened box, press E.',where:rs.holders.length?r:'STAGING',x:rs.holders.length?[-9,-3,3,9,22,28][+r.slice(1)-1]:DELIVERY.x,z:rs.holders.length?6:DELIVERY.z};}
 return {kind:s.holders.length?'mount':'pickup',stock:s.id,sku,rack:r,unit,units:c.units,title:s.holders.length?`Install ${name(sku)} in ${r}`:`Pick up ${name(sku)}`,detail:s.holders.length?`E installs at U${unit}. Automatic alignment.`:'Press E at the opened box. Solo lifting assistance is available.',where:s.holders.length?r:'STAGING',x:s.holders.length?[-9,-3,3,9,22,28][+r.slice(1)-1]:DELIVERY.x,z:s.holders.length?6:DELIVERY.z};
 }
 if(project.redundancy){const switches=installed.filter(n=>n.type==='switch'&&n.net.ip!=='0.0.0.0');for(const n of installed.filter(n=>['server','gpu'].includes(n.type))){const peers=new Set(links.filter(l=>!l.unplugged&&!l.disabled&&(l.a===n.id||l.b===n.id)).map(l=>l.a===n.id?l.b:l.a));for(const sw of switches.slice(0,2))if(!peers.has(sw.id)){const pa=n.ports.find(p=>!p.link&&p.speed===25&&!p.service),pb=sw.ports.find(p=>!p.link&&p.speed===25&&!p.service&&!p.reserved);if(pa&&pb)return cable(n,sw,pa,pb,'dac25');}}}
 const v=ops.validation();const pending=v.checks.find(c=>!c.ok);return pending?{kind:'configure',title:pending.text,detail:'J shows the requirement. Use the laptop for configuration and diagnostics.'}:{kind:'validate',title:'Submit the completed project',detail:'Press J → Validate & submit to collect the customer payment.'};
}
